package com.oasis.reservation.ui;
import com.oasis.reservation.service.ReservationService;import com.oasis.reservation.util.Theme;import javax.swing.*;import java.awt.*;import java.util.List;
public class DashboardPanel extends JPanel{
 private final ReservationService service=new ReservationService(); private final JLabel bookingCount=new JLabel("0"); private final JPanel recent=new JPanel();
 public DashboardPanel(String username){setOpaque(false);setBorder(BorderFactory.createEmptyBorder(20,24,24,24));setLayout(new BorderLayout(0,20));
  JPanel top=new JPanel(new BorderLayout());top.setOpaque(false);JPanel tt=new JPanel();tt.setOpaque(false);tt.setLayout(new BoxLayout(tt,BoxLayout.Y_AXIS));tt.add(Theme.heading("Good morning, "+username+" 👋",28));tt.add(Box.createVerticalStrut(5));tt.add(Theme.body("Manage journeys, reservations and live train information."));top.add(tt,BorderLayout.WEST);add(top,BorderLayout.NORTH);
  JPanel body=new JPanel(new BorderLayout(0,18));body.setOpaque(false);body.add(stats(),BorderLayout.NORTH);body.add(recentCard(),BorderLayout.CENTER);add(body,BorderLayout.CENTER);refresh();}
 private JPanel stats(){JPanel p=new JPanel(new GridLayout(1,3,14,0));p.setOpaque(false);p.add(stat(bookingCount.getText(),"Saved bookings","Your reservations"));p.add(stat("25+","Trains","Demo train catalogue"));p.add(stat("8","Rail APIs","Integrated API tools"));return p;}
 private JPanel stat(String value,String title,String sub){JPanel p=Theme.card();p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel v=Theme.heading(value,26);v.setForeground(Theme.BLUE);p.add(v);p.add(Box.createVerticalStrut(5));p.add(Theme.heading(title,14));p.add(Box.createVerticalStrut(3));p.add(Theme.body(sub));return p;}
 private JPanel recentCard(){JPanel p=Theme.card();p.setLayout(new BorderLayout(0,12));p.add(Theme.heading("Recent bookings",18),BorderLayout.NORTH);recent.setOpaque(false);recent.setLayout(new BoxLayout(recent,BoxLayout.Y_AXIS));JScrollPane s=new JScrollPane(recent);s.setBorder(null);p.add(s,BorderLayout.CENTER);return p;}
 public void refresh(){try{List<com.oasis.reservation.model.Reservation> rs=service.findAll();bookingCount.setText(String.valueOf(rs.size()));recent.removeAll();if(rs.isEmpty())recent.add(Theme.body("No bookings yet. Use Book Ticket to create your first reservation."));else for(var r:rs.stream().limit(5).toList()){JPanel row=Theme.softCard();row.setMaximumSize(new Dimension(Integer.MAX_VALUE,70));row.setLayout(new BorderLayout(12,0));JLabel left=Theme.heading(r.trainName(),14);JLabel mid=Theme.body(r.source()+"  →  "+r.destination()+"   •   "+r.journeyDate());JLabel pnr=Theme.body("PNR  "+r.pnr());row.add(left,BorderLayout.WEST);row.add(mid,BorderLayout.CENTER);row.add(pnr,BorderLayout.EAST);recent.add(row);recent.add(Box.createVerticalStrut(8));}recent.revalidate();recent.repaint();}catch(Exception e){bookingCount.setText("—");}}
}
